  .f.on { background: var(--ink); border-color: var(--ink); color: var(--card); font-weight: 600; }
  .f.ok { border-color: var(--cn); color: var(--cn); background: var(--cnbg); }
  .f.ok.on { background: var(--ok); border-color: var(--ok); color: var(--on-t1); }
